#!/bin/bash
# Comparative gate: zero NEW test failures vs recorded baseline.
# Usage: gate.sh api|web
set -u
APP="$1"
cd "/Users/jon.high/agency-access/apps/$APP" || exit 2
npx vitest run --reporter=json --outputFile="/tmp/gate-$APP.json" >/dev/null 2>&1
node -e "
const fs=require('fs');
const get=p=>{const r=JSON.parse(fs.readFileSync(p));return new Set(r.testResults.filter(s=>s.status==='failed').flatMap(s=>s.assertionResults.filter(a=>a.status==='failed').map(a=>a.fullName)))};
const base=get('/tmp/baseline-$APP-failures.txt'.replace('.txt','') && '/tmp/baseline-$APP-failures.txt');
const fs2=require('fs');
const baseSet=new Set(fs2.readFileSync('/tmp/baseline-$APP-failures.txt','utf8').split('\n').filter(Boolean));
const cur=get('/tmp/gate-$APP.json');
const news=[...cur].filter(x=>!baseSet.has(x));
const fixed=[...baseSet].filter(x=>!cur.has(x));
console.log('$APP: current failures',cur.size,'| baseline',baseSet.size,'| NEW:',news.length,'| fixed:',fixed.length);
news.forEach(x=>console.log('  NEW FAILURE:',x));
fixed.forEach(x=>console.log('  fixed vs baseline:',x));
process.exit(news.length?1:0);
"

