  // LINKEDIN PLATFORMS
  // ========================================================================

  linkedin: {
    name: 'LinkedIn',
    authUrl: 'https://www.linkedin.com/oauth/v2/authorization',
    tokenUrl: 'https://www.linkedin.com/oauth/v2/accessToken',
    scopeSeparator: ' ',
    userInfoUrl: 'https://api.linkedin.com/v2/userinfo',
    supportsRefreshTokens: true,
    // OIDC scopes (openid, profile, email) required for /v2/userinfo endpoint
    defaultScopes: ['openid', 'profile', 'email', 'rw_ads', 'r_ads_reporting'],
  },

  linkedin_ads: {
    name: 'LinkedIn Ads',
    authUrl: 'https://www.linkedin.com/oauth/v2/authorization',
    tokenUrl: 'https://www.linkedin.com/oauth/v2/accessToken',
    scopeSeparator: ' ',
    userInfoUrl: 'https://api.linkedin.com/v2/userinfo',
    supportsRefreshTokens: true,
    // OIDC scopes (openid, profile, email) required for /v2/userinfo endpoint
    defaultScopes: ['openid', 'profile', 'email', 'rw_ads', 'r_ads_reporting'],
  },

  linkedin_pages: {
    name: 'LinkedIn Pages',
    authUrl: 'https://www.linkedin.com/oauth/v2/authorization',
    tokenUrl: 'https://www.linkedin.com/oauth/v2/accessToken',
    scopeSeparator: ' ',
    userInfoUrl: 'https://api.linkedin.com/v2/userinfo',
    supportsRefreshTokens: true,
    defaultScopes: ['openid', 'profile', 'email', 'rw_organization_admin'],
  },

  // ========================================================================
  // KIT PLATFORMS
  // ========================================================================
  // Note: Kit uses team invitation flow (manual), not OAuth
  // This config is for type compatibility only
  // OAuth implementation preserved in kit.ts connector (commented out)

  kit: {
    name: 'Kit',
