  const allowedByEmail = email ? normalizedEmails.includes(email) : false;

  if (!allowedById && !allowedByEmail) {
    return {
      data: null,
      error: {
        code: 'FORBIDDEN',
        message: 'Internal admin access is required',
      },
    };
  }

  return {
    data: {
      userId,
      email,
    },
    error: null,
  };
}

