/**
 * Template Routes
 *
 * API endpoints for managing access request templates.
 * Protected by Clerk JWT verification.
 */

import { FastifyInstance } from 'fastify';
import { templateService } from '../services/template.service.js';
import { quotaMiddleware } from '../middleware/quota.middleware.js';
import { authenticate } from '@/middleware/auth.js';
import { assertAgencyAccess } from '@/lib/authorization.js';
import { requirePrincipalAgency } from '@/lib/agency-guard.js';

export async function templateRoutes(fastify: FastifyInstance) {
  fastify.addHook('onRequest', authenticate());
  fastify.addHook('onRequest', requirePrincipalAgency);

  // Get all templates for an agency
  fastify.get('/agencies/:agencyId/templates', async (request, reply) => {
    const { agencyId } = request.params as { agencyId: string };
    const principalAgencyId = (request as any).principalAgencyId as string;

    const accessError = assertAgencyAccess(agencyId, principalAgencyId);
    if (accessError) {
      return reply.code(403).send({ data: null, error: accessError });
    }

    const result = await templateService.getAgencyTemplates(agencyId);

    if (result.error) {
      return reply.code(500).send({
        data: null,
        error: result.error,
      });
    }

    return reply.send(result);
  });

  // Get single template by ID
  fastify.get('/templates/:id', async (request, reply) => {
    const { id } = request.params as { id: string };
    const principalAgencyId = (request as any).principalAgencyId as string;

    const result = await templateService.getTemplate(id);

    if (!result.error && result.data) {
      const accessError = assertAgencyAccess((result.data as any).agencyId, principalAgencyId);
      if (accessError) {
        return reply.code(403).send({ data: null, error: accessError });
      }
    }

    if (result.error) {
      const statusCode = result.error.code === 'NOT_FOUND' ? 404 : 400;
      return reply.code(statusCode).send({
        data: null,
        error: result.error,
      });
    }

    return reply.send(result);
  });

  // Create a new template
  fastify.post(
    '/agencies/:agencyId/templates',
    {
      onRequest: [quotaMiddleware({
        metric: 'templates',
        getAgencyId: (request) => (request.params as any).agencyId,
      })],
    },
    async (request, reply) => {
    const { agencyId } = request.params as { agencyId: string };
    const principalAgencyId = (request as any).principalAgencyId as string;
    const accessError = assertAgencyAccess(agencyId, principalAgencyId);
    if (accessError) {
      return reply.code(403).send({ data: null, error: accessError });
    }

    const input = { ...(request.body as any), agencyId };

    const result = await templateService.createTemplate(input);

    if (result.error) {
      const statusCode = result.error.code === 'DUPLICATE_NAME' ? 409 : 400;
      return reply.code(statusCode).send({
        data: null,
        error: result.error,
      });
    }

    return reply.code(201).send(result);
    },
  );

  // Update a template
  fastify.patch('/templates/:id', async (request, reply) => {
    const { id } = request.params as { id: string };
    const principalAgencyId = (request as any).principalAgencyId as string;

    const existing = await templateService.getTemplate(id);
    if (!existing.error && existing.data) {
      const accessError = assertAgencyAccess((existing.data as any).agencyId, principalAgencyId);
      if (accessError) {
        return reply.code(403).send({ data: null, error: accessError });
      }
    }

    const result = await templateService.updateTemplate(id, request.body as any);

    if (result.error) {
      const statusCode = result.error.code === 'NOT_FOUND' ? 404 : 400;
      return reply.code(statusCode).send({
        data: null,
        error: result.error,
      });
    }

    return reply.send(result);
  });

  // Delete a template
  fastify.delete('/templates/:id', async (request, reply) => {
    const { id } = request.params as { id: string };
    const principalAgencyId = (request as any).principalAgencyId as string;

    const existing = await templateService.getTemplate(id);
    if (!existing.error && existing.data) {
      const accessError = assertAgencyAccess((existing.data as any).agencyId, principalAgencyId);
      if (accessError) {
        return reply.code(403).send({ data: null, error: accessError });
      }
    }

    const result = await templateService.deleteTemplate(id);

    if (result.error) {
      return reply.code(404).send({
        data: null,
        error: result.error,
      });
    }

    return reply.send({ data: { success: true }, error: null });
  });

  // Set template as default
  fastify.post('/templates/:id/set-default', async (request, reply) => {
    const { id } = request.params as { id: string };
    const principalAgencyId = (request as any).principalAgencyId as string;

    const existing = await templateService.getTemplate(id);
    if (!existing.error && existing.data) {
      const accessError = assertAgencyAccess((existing.data as any).agencyId, principalAgencyId);
      if (accessError) {
        return reply.code(403).send({ data: null, error: accessError });
      }
    }

    const result = await templateService.setDefaultTemplate(id);

    if (result.error) {
      return reply.code(404).send({
        data: null,
        error: result.error,
      });
    }

    return reply.send(result);
  });
}

import type { FastifyRequest } from 'fastify';
import { agencyResolutionService } from '@/services/agency-resolution.service';

export interface AuthorizationError {
  code: string;
  message: string;
}

export interface PrincipalAgencyData {
  agencyId: string;
  principalId: string;
  agency: {
    id: string;
    name: string;
    email: string;
  };
}

export interface AuthUserClaims {
  sub?: string;
  orgId?: string;
  email?: string;
  email_address?: string;
  emailAddress?: string;
  email_addresses?: Array<{ email_address?: string; emailAddress?: string }>;
}

export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

export function resolveUserEmail(user: AuthUserClaims | undefined): string | undefined {
  const direct = user?.email || user?.email_address || user?.emailAddress;
  if (direct) return normalizeEmail(direct);

  const firstEmail = user?.email_addresses?.[0];
  if (!firstEmail) return undefined;

  const nested = firstEmail.email_address || firstEmail.emailAddress;
  if (!nested) return undefined;

  return normalizeEmail(nested);
}

export async function resolvePrincipalAgency(
  request: FastifyRequest
): Promise<{ data: PrincipalAgencyData | null; error: AuthorizationError | null }> {
  const user = (request as any).user as AuthUserClaims | undefined;
  const principalId = user?.orgId || user?.sub;

  if (!principalId) {
    return {
      data: null,
      error: {
        code: 'UNAUTHORIZED',
        message: 'Authenticated user context is required',
      },
    };
  }

  const userEmail = resolveUserEmail(user);
  const buildPrincipalData = (agencyResultData: {
    agencyId: string;
    agency: {
      id: string;
      name: string;
      email: string;
    };
  }): PrincipalAgencyData => ({
    agencyId: agencyResultData.agencyId,
    principalId,
    agency: {
      id: agencyResultData.agency.id,
      name: agencyResultData.agency.name,
      email: agencyResultData.agency.email,
    },
  });

  // Cache-first lookup: avoid create-if-missing on the hot path for existing users.
  const cacheFirstResult = await agencyResolutionService.resolveAgency(principalId, {
    createIfMissing: false,
    userEmail,
  });

  if (cacheFirstResult.data) {
    return {
      data: buildPrincipalData(cacheFirstResult.data),
      error: null,
    };
  }

  // Only fallback to create-if-missing when agency does not exist.
  const createIfMissingResult = await agencyResolutionService.resolveAgency(principalId, {
    createIfMissing: true,
    userEmail,
  });

  if (createIfMissingResult.error || !createIfMissingResult.data) {
    return {
      data: null,
      error: {
        code: 'FORBIDDEN',
        message: 'Unable to resolve agency for authenticated user',
      },
    };
  }

  return {
    data: buildPrincipalData(createIfMissingResult.data),
    error: null,
  };
}

export function assertAgencyAccess(
  requestedAgencyId: string,
  principalAgencyId: string
): AuthorizationError | null {
  if (requestedAgencyId !== principalAgencyId) {
    return {
      code: 'FORBIDDEN',
      message: 'You do not have access to this agency resource',
    };
  }

  return null;
}

import type { FastifyReply, FastifyRequest } from 'fastify';
import {
  assertAgencyAccess,
  resolvePrincipalAgency,
  type PrincipalAgencyData,
} from './authorization.js';

/**
 * Shared preHandler: resolve the caller's agency, attach it to the request,
 * and reply 401/403 exactly like the per-route copies it replaced.
 * Returns the principal data (or null after replying) for routes that
 * await it inline instead of registering it as a hook.
 *
 * Lives outside authorization.ts so resolvePrincipalAgency is called
 * through the module boundary — route tests mock that module.
 */
export async function requirePrincipalAgency(
  request: FastifyRequest,
  reply: FastifyReply
): Promise<PrincipalAgencyData | null> {
  const principalResult = await resolvePrincipalAgency(request);
  if (principalResult.error || !principalResult.data) {
    const statusCode = principalResult.error?.code === 'UNAUTHORIZED' ? 401 : 403;
    reply.code(statusCode).send({
      data: null,
      error: principalResult.error || {
        code: 'FORBIDDEN',
        message: 'Unable to resolve agency for authenticated user',
      },
    });
    return null;
  }

  (request as any).principalAgencyId = principalResult.data.agencyId;
  (request as any).agencyId = principalResult.data.agencyId;
  (request as any).principalId = principalResult.data.principalId;
  return principalResult.data;
}

/**
 * Shared route-agency guard: verify the :id (or :agencyId) route param
 * matches the principal agency. Replies 403 on mismatch and returns null;
 * returns the route agency id when access is allowed.
 */
export function enforceRouteAgency(
  request: FastifyRequest,
  reply: FastifyReply,
  paramName: 'id' | 'agencyId' = 'id'
): string | null {
  const routeAgencyId = (request.params as Record<string, string>)[paramName];
  const accessError = assertAgencyAccess(routeAgencyId, (request as any).principalAgencyId);
  if (accessError) {
    void reply.code(403).send({ data: null, error: accessError });
    return null;
  }
  return routeAgencyId;
}

import type { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';
import { z } from 'zod';
import { AgentPermissionSchema } from '@agency-platform/shared';
import { enforceRouteAgency, requirePrincipalAgency } from '@/lib/agency-guard.js';
import { extractClientIp, extractUserAgent } from '@/lib/ip.js';
import { authenticate } from '@/middleware/auth.js';
import { agentGrantService } from '@/services/agent-grant.service.js';
import { agentRolloutService } from '@/services/agent-rollout.service.js';
import { sendError } from '../lib/response.js';

const CreateGrantSchema = z.object({
  oauthClientId: z.string().min(1).max(200),
  displayName: z.string().min(1).max(120),
  permissions: AgentPermissionSchema.array().min(1),
});

const UpdateGrantSchema = z
  .object({
    displayName: z.string().min(1).max(120).optional(),
    permissions: AgentPermissionSchema.array().min(1).optional(),
  })
  .refine((value) => Object.keys(value).length > 0, {
    message: 'At least one grant field is required',
  });

function ownerSubject(request: FastifyRequest): string | null {
  const user = (request as any).user as { sub?: string } | undefined;
  return user?.sub || null;
}

function requestMetadata(request: FastifyRequest) {
  return {
    ipAddress: extractClientIp(request),
    userAgent: extractUserAgent(request),
    correlationId: request.id,
  };
}

export async function agentGrantRoutes(fastify: FastifyInstance) {
  const ownerHooks = [authenticate(), requirePrincipalAgency];

  fastify.get('/agencies/:id/agent-grants', { onRequest: ownerHooks }, async (request, reply) => {
    const agencyId = enforceRouteAgency(request, reply);
    if (!agencyId) return;
    return reply.send({ data: await agentGrantService.listGrants(agencyId) });
  });

  fastify.post('/agencies/:id/agent-grants', { onRequest: ownerHooks }, async (request, reply) => {
    const agencyId = enforceRouteAgency(request, reply);
    if (!agencyId) return;
    if (!agentRolloutService.isAgencyAllowed(agencyId)) return sendError(reply, 'NOT_FOUND', 'Agent access is not enabled for this agency', 404);
    const subject = ownerSubject(request);
    if (!subject) {
      return sendError(reply, 'UNAUTHORIZED', 'Authenticated owner identity is required', 401);
    }

    const parsed = CreateGrantSchema.safeParse(request.body);
    if (!parsed.success) {
      return sendError(reply, 'VALIDATION_ERROR', 'Invalid agent grant', 400, parsed.error.flatten(),);
    }

    const grant = await agentGrantService.createOrReactivateGrant({
      agencyId,
      ownerSubject: subject,
      ...parsed.data,
      requestMetadata: requestMetadata(request),
    });
    return reply.code(201).send({ data: grant });
  });

  fastify.patch('/agencies/:id/agent-grants/:grantId', { onRequest: ownerHooks }, async (request, reply) => {
    const agencyId = enforceRouteAgency(request, reply);
    if (!agencyId) return;
    const subject = ownerSubject(request);
    if (!subject) return sendError(reply, 'UNAUTHORIZED', 'Authenticated owner identity is required', 401);

    const parsed = UpdateGrantSchema.safeParse(request.body);
    if (!parsed.success) {
      return sendError(reply, 'VALIDATION_ERROR', 'Invalid agent grant update', 400, parsed.error.flatten());
    }

    const { grantId } = request.params as { grantId: string };
    const grant = await agentGrantService.updateGrant({
      agencyId,
      grantId,
      updatedBy: subject,
      ...parsed.data,
      requestMetadata: requestMetadata(request),
    });
    if (!grant) return sendError(reply, 'NOT_FOUND', 'Agent grant not found', 404);
    return reply.send({ data: grant });
  });

  fastify.delete('/agencies/:id/agent-grants/:grantId', { onRequest: ownerHooks }, async (request, reply) => {
    const agencyId = enforceRouteAgency(request, reply);
    if (!agencyId) return;
    const subject = ownerSubject(request);
    if (!subject) return sendError(reply, 'UNAUTHORIZED', 'Authenticated owner identity is required', 401);

    const { grantId } = request.params as { grantId: string };
    const revoked = await agentGrantService.revokeGrant({
      agencyId,
      grantId,
      revokedBy: subject,
      requestMetadata: requestMetadata(request),
    });
    if (!revoked) return sendError(reply, 'NOT_FOUND', 'Active agent grant not found', 404);
    return reply.send({ data: { id: grantId, state: 'revoked' } });
  });
}

/**
 * Access Request Routes
 *
 * API endpoints for creating and managing access requests.
 * Protected by Clerk JWT verification.
 */

import { FastifyInstance } from 'fastify';
import { accessRequestService } from '../services/access-request.service.js';
import { agencyPlatformService } from '../services/agency-platform.service.js';
import { auditService } from '../services/audit.service.js';
import { quotaMiddleware } from '../middleware/quota.middleware.js';
import { authenticate } from '@/middleware/auth.js';
import { assertAgencyAccess } from '@/lib/authorization.js';
import { requirePrincipalAgency } from '@/lib/agency-guard.js';
import { sendError } from '../lib/response.js';

const ACCESS_LEVEL_MAP: Record<string, 'manage' | 'view_only'> = {
  admin: 'manage',
  standard: 'manage',
  read_only: 'view_only',
  email_only: 'view_only',
  manage: 'manage',
  view_only: 'view_only',
};

function toPlatformGroup(platform: string): string {
  if (!platform) return '';
  if (
    platform === 'ga4' ||
    platform === 'youtube_studio' ||
    platform === 'display_video_360' ||
    platform.startsWith('google_')
  ) {
    return 'google';
  }
  if (platform === 'instagram' || platform === 'whatsapp_business' || platform.startsWith('meta_')) {
    return 'meta';
  }
  if (platform.startsWith('linkedin')) return 'linkedin';
  if (platform.startsWith('tiktok')) return 'tiktok';
  if (platform.startsWith('snapchat')) return 'snapchat';
  return platform.split('_')[0] || platform;
}

function normalizePlatformsPayload(platforms: any): Array<{ platform: string; accessLevel: 'manage' | 'view_only'; accountId?: string }> {
  if (Array.isArray(platforms)) {
    return platforms.flatMap((entry: any) => {
      if (entry?.platformGroup && Array.isArray(entry.products)) {
        return entry.products
          .filter((product: any) => typeof product?.product === 'string')
          .map((product: any) => {
            const base = {
              platform: product.product,
              accessLevel: ACCESS_LEVEL_MAP[product.accessLevel] || 'manage' as const,
            };
            if (typeof product.accountId === 'string' && product.accountId.trim().length > 0) {
              return { ...base, accountId: product.accountId.trim() };
            }
            return base;
          });
      }

      if (typeof entry?.platform === 'string') {
        const base = {
          platform: entry.platform,
          accessLevel: ACCESS_LEVEL_MAP[entry.accessLevel] || 'manage' as const,
        };
        if (typeof entry.accountId === 'string' && entry.accountId.trim().length > 0) {
          return [{ ...base, accountId: entry.accountId.trim() }];
        }
        return [base];
      }

      if (typeof entry === 'string') {
        return [{
          platform: entry,
          accessLevel: 'manage' as const,
        }];
      }

      return [];
    });
  }

  if (platforms && typeof platforms === 'object') {
    return Object.entries(platforms).flatMap(([_, products]) => {
      if (!Array.isArray(products)) return [];
      return products
        .filter((product) => typeof product === 'string')
        .map((product) => ({
          platform: product,
          accessLevel: 'manage' as const,
        }));
    });
  }

  return [];
}

export async function accessRequestRoutes(fastify: FastifyInstance) {

  // Create access request
  fastify.post(
    '/access-requests',
    {
      onRequest: [
        authenticate(),
        requirePrincipalAgency,
        quotaMiddleware({
          metric: 'access_requests',
          getAgencyId: (request) => (request as any).agencyId,
        }),
      ],
    },
    async (request, reply) => {
    const requestBody = request.body as any;
    const originalPlatforms = requestBody.platforms ?? [];
    const transformedPlatforms = normalizePlatformsPayload(originalPlatforms);
    const principalAgencyId = (request as any).principalAgencyId as string;

    const resolvedAgencyId = principalAgencyId;
    // Update the request body with the resolved agencyId
    requestBody.agencyId = resolvedAgencyId;

    // Log transformation for debugging
    fastify.log.info({
      originalPlatforms,
      transformedPlatforms,
      platformCount: transformedPlatforms.length,
    });

    // Update request body with transformed platforms
    const transformedRequestBody = {
      ...requestBody,
      platforms: transformedPlatforms,
    };

    // Proceed with access request creation
    const result = await accessRequestService.createAccessRequest(transformedRequestBody);

    if (result.error) {
      const statusCode = result.error.code === 'SUBDOMAIN_TAKEN' ? 409 : 400;
      return reply.code(statusCode).send({
        data: null,
        error: result.error,
      });
    }

    return reply.code(201).send(result);
    },
  );

  // Get access request by unique token (for client authorization flow - no auth required)
  fastify.get('/client/:token', async (request, reply) => {
    const { token } = request.params as { token: string };

    const result = await accessRequestService.getAccessRequestByToken(token);

    if (result.error) {
      const statusCode = (
        result.error.code === 'NOT_FOUND' ||
        result.error.code === 'EXPIRED' ||
        result.error.code === 'REQUEST_NOT_FOUND' ||
        result.error.code === 'REQUEST_EXPIRED'
      ) ? 404 : 400;
      return reply.code(statusCode).send({
        data: null,
        error: result.error,
      });
    }

    return reply.send(result);
  });

  // Get all access requests for an agency
  fastify.get('/agencies/:id/access-requests', {
    onRequest: [authenticate(), requirePrincipalAgency],
  }, async (request, reply) => {
    const { id } = request.params as { id: string };
    const { status, limit, offset } = request.query as any;
    const principalAgencyId = (request as any).principalAgencyId as string;

    const accessError = assertAgencyAccess(id, principalAgencyId);
    if (accessError) {
      return reply.code(403).send({
        data: null,
        error: accessError,
      });
    }

    const result = await accessRequestService.getAgencyAccessRequests(id, {
      status,
      limit: limit ? parseInt(limit) : undefined,
      offset: offset ? parseInt(offset) : undefined,
    });

    if (result.error) {
      return reply.code(500).send({
        data: null,
        error: result.error,
      });
    }

    return reply.send(result);
  });

  // Get single access request by ID
  fastify.get('/access-requests/:id', {
    onRequest: [authenticate(), requirePrincipalAgency],
  }, async (request, reply) => {
    const { id } = request.params as { id: string };
    const principalAgencyId = (request as any).principalAgencyId as string;

    const result = await accessRequestService.getAccessRequestById(id);

    if (!result.error && result.data) {
      const accessError = assertAgencyAccess((result.data as any).agencyId, principalAgencyId);
      if (accessError) {
        return reply.code(403).send({
          data: null,
          error: accessError,
        });
      }
    }

    if (result.error) {
      return reply.code(404).send({
        data: null,
        error: result.error,
      });
    }

    const shopifySubmission = (result.data as any)?.shopifySubmission;
    if (
      shopifySubmission &&
      (shopifySubmission.status === 'submitted' || shopifySubmission.status === 'legacy_unreadable')
    ) {
      await auditService.createAuditLog({
        agencyId: (result.data as any).agencyId,
        userEmail:
          ((request as any).user?.email as string | undefined) ||
          ((request as any).user?.sub as string | undefined) ||
          'agency',
        action: 'SHOPIFY_SUBMISSION_VIEWED',
        resourceType: 'access_request',
        resourceId: id,
        metadata: {
          shopifySubmissionStatus: shopifySubmission.status,
          hasCollaboratorCode: typeof shopifySubmission.collaboratorCode === 'string',
          shopDomain: shopifySubmission.shopDomain,
          connectionId: shopifySubmission.connectionId,
        },
        request,
      });
    }

    return reply.send(result);
  });

  // Update access request
  fastify.patch('/access-requests/:id', {
    onRequest: [authenticate(), requirePrincipalAgency],
  }, async (request, reply) => {
    const { id } = request.params as { id: string };
    const principalAgencyId = (request as any).principalAgencyId as string;
    const requestBody = request.body as any;

    const existing = await accessRequestService.getAccessRequestById(id);
    if (!existing.error && existing.data) {
      const accessError = assertAgencyAccess((existing.data as any).agencyId, principalAgencyId);
      if (accessError) {
        return reply.code(403).send({
          data: null,
          error: accessError,
        });
      }
    }

    const identityFields = ['clientName', 'clientEmail'].filter((field) => requestBody?.[field] !== undefined);
    if (identityFields.length > 0) {
      return sendError(reply, 'VALIDATION_ERROR', 'Client identity fields must be edited in client profile management', 400, { fields: identityFields });
    }

    const transformedRequestBody = {
      ...requestBody,
      ...(requestBody?.platforms !== undefined
        ? { platforms: normalizePlatformsPayload(requestBody.platforms) }
        : {}),
    };

    const result = await accessRequestService.updateAccessRequest(id, transformedRequestBody as any);

    if (result.error) {
      const statusCode = result.error.code === 'NOT_FOUND' ? 404 : 400;
      return reply.code(statusCode).send({
        data: null,
        error: result.error,
      });
    }

    return reply.send(result);
  });

  // Mark request as authorized (called after successful OAuth)
  fastify.post('/access-requests/:id/authorize', {
    onRequest: [authenticate(), requirePrincipalAgency],
  }, async (request, reply) => {
    const { id } = request.params as { id: string };
    const principalAgencyId = (request as any).principalAgencyId as string;

    const existing = await accessRequestService.getAccessRequestById(id);
    if (!existing.error && existing.data) {
      const accessError = assertAgencyAccess((existing.data as any).agencyId, principalAgencyId);
      if (accessError) {
        return reply.code(403).send({
          data: null,
          error: accessError,
        });
      }
    }

    const result = await accessRequestService.markRequestAuthorized(id);

    if (result.error) {
      return reply.code(404).send({
        data: null,
        error: result.error,
      });
    }

    return reply.send(result);
  });

  // Cancel access request
  fastify.post('/access-requests/:id/cancel', {
    onRequest: [authenticate(), requirePrincipalAgency],
  }, async (request, reply) => {
    const { id } = request.params as { id: string };
    const principalAgencyId = (request as any).principalAgencyId as string;

    const existing = await accessRequestService.getAccessRequestById(id);
    if (!existing.error && existing.data) {
      const accessError = assertAgencyAccess((existing.data as any).agencyId, principalAgencyId);
      if (accessError) {
        return reply.code(403).send({
          data: null,
          error: accessError,
        });
      }
    }

    const result = await accessRequestService.cancelAccessRequest(id);

    if (result.error) {
      return reply.code(404).send({
        data: null,
        error: result.error,
      });
    }

    if (existing.data) {
      await auditService.createAuditLog({
        agencyId: (existing.data as any).agencyId,
        userEmail:
          ((request as any).user?.email as string | undefined) ||
          ((request as any).user?.sub as string | undefined) ||
          'agency',
        action: 'ACCESS_REQUEST_REVOKED',
        resourceType: 'access_request',
        resourceId: id,
        metadata: {
          clientName: (existing.data as any).clientName,
          clientEmail: (existing.data as any).clientEmail,
        },
        request,
      });
    }

    return reply.send({ data: { success: true }, error: null });
  });
}

